import { defineCard } from "../define.js";

// EDHREC rank 20781. Modern Horizons 3.
//
// Shrine of the Forsaken Gods' colorless-spell restriction plus Guidelight
// Optimizer's "or to activate an ability" — any ability, of any source in any
// zone (the ruling).
//
// Rulings:
//   [2024-06-07] The mana generated by Sage of the Unknowable's activated ability can be used to
//     activate any ability, not just abilities of colorless sources.

const MANA_TEXT = "{T}: Add {C}. Spend this mana only to cast a colorless spell or to activate an ability.";

export default defineCard({
  name: "Sage of the Unknowable",
  manaCost: "{1}{U}",
  colors: ["U"],
  types: ["creature"],
  subtypes: ["Human", "Wizard"],
  power: 0,
  toughness: 4,
  text: MANA_TEXT,
  activated: [
    {
      cost: { mana: null, tap: true },
      targets: [],
      effect: {
        kind: "add-mana",
        mana: "C",
        amount: 1,
        spendOnly: {
          spell: { colorless: true },
          abilityOf: {},
          abilityOfAnyZone: true,
          text: "Spend this mana only to cast a colorless spell or to activate an ability.",
        },
      },
      resolve: null,
      text: MANA_TEXT,
    },
  ],
});
